
import { Box, Button, Container, TextField, ThemeProvider, Typography } from "@mui/material";
import Navbar from "../../components/Navbar";
import { theme } from "../../theme";
import { useLocation } from "react-router-dom";

interface ContactProps {
    overview?: string;
    description?: string;
}

export default function Contact(props: ContactProps) {
    const location = useLocation();
    return (
        <ThemeProvider theme={theme}>
            {location.pathname !== "/" && <Navbar />}
            <Box sx={{ backgroundColor: location.pathname === "/" ? '#edf3fc' : '' }}>
                <Container maxWidth="lg" sx={{ textAlign: 'center' }}>
                    <Box sx={{ paddingTop: 10, paddingBottom: 10 }}>
                        <Typography variant="h5" sx={{ fontWeight: 'bold', padding: 3, textAlign: 'justify' }}>
                            Contact Me
                        </Typography>
                        <Typography variant="body1" sx={{ textAlign: 'justify' }}>
                            If you’d like to chat about a project or just have question, please fill in the form below. I aim to get back within 2 days.
                        </Typography>

                        <Box
                            component="form"
                            sx={{
                                '& .MuiTextField-root': { m: 1 },
                            }}
                            noValidate
                            autoComplete="off"
                        >
                            <div>
                                <TextField
                                    id="name"
                                    name="name"
                                    label="Name"
                                    sx={{
                                        width: '40%',
                                        textAlign: 'left'
                                    }}
                                />
                                <TextField
                                    id="email"
                                    name="email"
                                    type="email"
                                    label="Email"
                                    sx={{
                                        width: '40%',
                                        textAlign: 'left'
                                    }}
                                />
                            </div>
                            <div>
                                <TextField
                                    id="subject"
                                    name="subject"
                                    type="subject"
                                    label="Subject"
                                    sx={{
                                        width: '80%',
                                        textAlign: 'left'
                                    }}
                                />
                            </div>

                            <div>
                                <TextField
                                    id="message"
                                    name="message"
                                    type="message"
                                    label="Message"
                                    rows={4}
                                    multiline
                                    sx={{
                                        width: '80%',
                                        textAlign: 'left'
                                    }}
                                />
                            </div>
                            <Button variant="contained" disabled>Send Message</Button>

                        </Box>
                    </Box>

                </Container>
            </Box>
        </ThemeProvider>
    )
}