import { ThemeProvider } from '@mui/material/styles';
import Navbar from '../../components/Navbar';
import { theme } from '../../theme';
import { Alert, Box, Chip, Container, Grid, Stack, Typography } from '@mui/material';
import { Link, useNavigate, useParams } from 'react-router-dom';
import { useEffect, useState } from 'react';
import { workLists } from '../../storage';
import { Work } from '../../interfaces/WorkInformation';
import { LINK_TEXT_TYPE, LINK_VIDEO_TYPE } from '../../constants/linkTypes';
import './index.css';

export default function WorkInformation() {
    const { workId } = useParams();
    const navigate = useNavigate();
    const [workInfo, setWorkInfo] = useState<Work>({});

    useEffect(() => {
        const workInformation = workLists.find(x => x.id === workId) as Work;
        if (workInformation) {
            setWorkInfo(workInformation);
        } else {
            navigate(`/work`);
        }
    }, [workId]);

    return (
        <ThemeProvider theme={theme}>
            <Navbar />
            <Container>

                <Box sx={{ paddingTop: 5, paddingBottom: 5 }}>
                    <Typography variant="h5" sx={{ textAlign: 'justify' }}>
                        {workInfo.title}
                        {/* 
                        SUNLIFE REFERENCE
                        digisig - https://onboard-help.sunlifeconnect.com/hc/en-us/articles/4403015553427-Managing-DocuSign-Onboarding-Forms
                        
                        */}

                        {/* 
                        ubp
                        1uhub - https://www.oneunionbankerhub.com/#/
                        */}
                    </Typography>
                    <Typography variant="body1" sx={{ textAlign: 'justify' }}>
                        {workInfo.description}
                    </Typography>

                    {workInfo.skills && (
                        <Box>
                            <Typography variant="h5" sx={{ textAlign: 'justify', paddingTop: 3, paddingBottom: 1 }}>
                                Skills used:
                            </Typography>
                            <Alert variant="outlined" icon={false} severity="success">
                                <Box>
                                    <Stack direction="row" spacing={2} useFlexGap flexWrap="wrap">
                                        {workInfo.skills.map(skill => (
                                            <Link to={skill.link} target='_blank'>
                                                <Chip label={skill.name} color="primary" variant="outlined" />
                                            </Link>
                                        ))}
                                    </Stack>
                                    {(workInfo.additionalSkillName && workInfo.additionalSkils) && (
                                        <Box>
                                            <Typography variant="body2" sx={{ textAlign: 'justify', paddingTop: 3, paddingBottom: 1 }}>
                                                {workInfo.additionalSkillName}
                                            </Typography>
                                            <Stack direction="row" spacing={2} useFlexGap flexWrap="wrap">
                                                {workInfo.additionalSkils?.map((additionalSkill) => (
                                                    <Link to={additionalSkill.link} target='_blank'>
                                                        <Chip label={additionalSkill.name} color="primary" variant="outlined" />
                                                    </Link>
                                                ))}
                                            </Stack>
                                        </Box>
                                    )}

                                </Box>
                            </Alert>
                        </Box>
                    )}

                    {workInfo.screenshots && (
                        <Box sx={{ textAlign: '-webkit-center', paddingTop: 10, paddingBottom: 1 }}>
                            <Typography variant="h5" sx={{ textAlign: 'justify', paddingTop: 3, paddingBottom: 1 }}>
                                Screenshots:
                            </Typography>
                            <Grid container spacing={3}>
                                {
                                    workInfo.screenshots.map((item, i) => (
                                        <Grid item xs={12} md={6} lg={6}>
                                            <img key={item.alt} src={process.env.PUBLIC_URL + item.path} style={{ width: '100%', height: '100%' }} />)
                                        </Grid>
                                    ))
                                }
                            </Grid>
                        </Box>
                    )}

                    {workInfo?.links && (
                        <Box sx={{ textAlign: '-webkit-center', paddingTop: 10, paddingBottom: 1 }}>
                            <Typography variant="h5" sx={{ textAlign: 'justify', }}>
                                Reference:
                            </Typography>
                            <Box>
                                {workInfo.links.map(link => {
                                    if (link.type === LINK_VIDEO_TYPE) {
                                        return <Box className='iframe-container'>
                                            <iframe
                                                src={link.url}
                                                className='responsive-iframe'
                                                allow="autoplay; clipboard-write; encrypted-media; picture-in-picture; web-share"
                                            ></iframe>
                                        </Box>
                                    }
                                    if (link.type === LINK_TEXT_TYPE) {
                                        return (
                                            <Box>
                                                <Link to={link.url} target='_blank'>
                                                    <Typography variant="h6" sx={{ textAlign: 'justify', }}>
                                                        {link.title}
                                                    </Typography>
                                                </Link>
                                            </Box>
                                        )
                                    }
                                })}

                            </Box>
                        </Box>
                    )}
                </Box>
            </Container>

        </ThemeProvider >
    );
}
