import { Box, Container, Typography } from "@mui/material";

interface HeaderProps {
    description?: string;
}

export default function Header(props: HeaderProps) {
    return (
        <Container maxWidth="lg" sx={{ marginTop: 6, textAlignLast: 'center' }} className='fit-to-screen'>
            <Box sx={{ width: '100%' }} >
                <Typography variant="h4" className='header-text'>
                    {"<Full-stack Developer/>"}
                </Typography>
                <Typography variant="h6" gutterBottom>
                    {props.description}
                </Typography>
            </Box>
            <img src={process.env.PUBLIC_URL + '/header-banner.png'} style={{ width: '60%' }} />
        </Container>
    )
}